 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find zero cells connected to the grid edge by 4-way motion.
    outside = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r == 0 or c == 0 or r == h - 1 or c == w - 1):
                outside.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                q.append((nr, nc))

    inside = {
        (r, c)
        for r in range(h)
        for c in range(w)
        if grid[r][c] == 0 and (r, c) not in outside
    }

    # Activate each 4-connected group of 1s bordering an enclosed zero pocket.
    seen = set()
    active = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            component = set()
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                component.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 1
                            and p not in seen):
                        seen.add(p)
                        q.append(p)
            if any((y + dy, x + dx) in inside
                   for y, x in component
                   for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                active.update(component)

    # Color zero cells in the 8-neighbor halo by whether they are inside or outside.
    for r, c in active:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if not (dr or dc):
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                    out[nr][nc] = 3 if (nr, nc) in inside else 2
    return out
